import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"NetPilot — Kit de red en Go","description":"Un kit de herramientas de red en un solo binario, en Go puro: escáner de puertos, TCP ping, comprobaciones HTTP y DNS. Sin dependencias, multiplataforma.","frontmatter":{"title":"NetPilot — Kit de red en Go","description":"Un kit de herramientas de red en un solo binario, en Go puro: escáner de puertos, TCP ping, comprobaciones HTTP y DNS. Sin dependencias, multiplataforma."},"headers":[],"relativePath":"es/projects/netpilot/index.md","filePath":"es/projects/netpilot/index.md"}`),a={name:`es/projects/netpilot/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="netpilot-—-kit-de-red-en-go" tabindex="-1">NetPilot — Kit de red en Go <a class="header-anchor" href="#netpilot-—-kit-de-red-en-go" aria-label="Permalink to “NetPilot — Kit de red en Go”">​</a></h1><p><strong><a href="https://github.com/Godde3s/netpilot" target="_blank" rel="noreferrer">NetPilot</a></strong> es mi respuesta a una molestia simple: verificar la conectividad de red no debería requerir instalar cinco herramientas distintas ni memorizar los flags de <code>nmap</code>. NetPilot compila a <strong>un único binario estático en Go puro</strong> — sin runtime, sin dependencias, sin scripts — y responde las preguntas que le hago a las redes todos los días.</p><h2 id="lo-que-hace" tabindex="-1">Lo que hace <a class="header-anchor" href="#lo-que-hace" aria-label="Permalink to “Lo que hace”">​</a></h2><table tabindex="0"><thead><tr><th>Comando</th><th>Trabajo</th></tr></thead><tbody><tr><td><code>scan</code></td><td>Escaneo rápido de puertos TCP con pools de workers y timeouts.</td></tr><tr><td><code>tping</code></td><td>Ping a nivel TCP que funciona donde ICMP está bloqueado.</td></tr><tr><td><code>http</code></td><td>Comprobaciones de salud HTTP con estado, latencia e info TLS.</td></tr><tr><td><code>dns</code></td><td>Consultas A/AAAA/MX/TXT contra cualquier resolver.</td></tr><tr><td><code>info</code></td><td>Resumen de interfaces y rutas para triage rápido.</td></tr></tbody></table><h2 id="por-que-go-puro" tabindex="-1">Por qué Go puro <a class="header-anchor" href="#por-que-go-puro" aria-label="Permalink to “Por qué Go puro”">​</a></h2><p>Porque el despliegue es todo el punto. Una herramienta de red que necesita Python, Node o una docena de librerías del sistema falla exactamente donde más la necesitas: un VPS mínimo, un contenedor en un clúster roto, o la laptop Windows de un amigo a las 2 AM. <code>go build</code> produce un binario por plataforma; <code>CGO_ENABLED=0</code> lo mantiene portable. El modelo de concurrencia (goroutines + channels) hace rápido al escáner sin dolores de threads.</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># escanear el rango de puertos conocidos de un host</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./netpilot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ports</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1-1024</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workers</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 200</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># tcp-ping a un servicio inestable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./netpilot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tping</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db.internal:5432</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --count</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># health-check con salida JSON para scripts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./netpilot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://api.example.com/health</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><h2 id="lo-que-aprendi-construyendolo" tabindex="-1">Lo que aprendí construyéndolo <a class="header-anchor" href="#lo-que-aprendi-construyendolo" aria-label="Permalink to “Lo que aprendí construyéndolo”">​</a></h2><p>La ingeniería interesante no fue el escaneo — fueron los casos límite: limitar tu propia tasa para no tumbar tu gateway, manejar conexiones medio abiertas, honrar timeouts que de verdad significan algo, y hacer que la salida JSON sea lo bastante estable para escribir scripts sobre ella. También se convirtió en mi proyecto de referencia para entender hasta dónde puede llegar un equipo de agentes con un CLI bien especificado.</p><div class="tip custom-block"><p class="custom-block-title">Pruébalo</p><p>Clona, <code>go build</code>, listo: <a href="https://github.com/Godde3s/netpilot" target="_blank" rel="noreferrer">github.com/Godde3s/netpilot</a> — licencia MIT.</p></div>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};